import osos.environ["PYTORCH_ENABLE_MPS_FALLBACK"] = "1"import scanpy as scimport numpy as npimport scipy.sparse as spimport matplotlib.pyplot as pltimport cell2locationfrom cell2location.models import RegressionModelimport torchif __name__ == '__main__':    # ── Paths ──────────────────────────────────────────────────────────────    results_folder = "C:/Users/Gabe/Desktop/multiome_poa/Python/cell2location/results_2026_06_17"    ref_run_name   = f"{results_folder}/reference_signatures"    os.makedirs(ref_run_name, exist_ok=True)    # ── Load ───────────────────────────────────────────────────────────────    adata_ref = sc.read_h5ad("C:/Users/Gabe/Desktop/multiome_ref.h5ad")    print(adata_ref)    # ── Raw counts to .X ───────────────────────────────────────────────────    if "counts" in adata_ref.layers:        adata_ref.X = adata_ref.layers["counts"].copy()    if sp.issparse(adata_ref.X):        adata_ref.X = adata_ref.X.toarray()    print("Count matrix sample:", adata_ref.X[:3, :5])    print("Max value:", adata_ref.X.max())    # ── Gene filter ────────────────────────────────────────────────────────    sc.pp.filter_genes(adata_ref, min_cells=10)    # ── Setup ──────────────────────────────────────────────────────────────    CELL_TYPE_KEY = "res0.8_50nn_40PC_45LSI"    BATCH_KEY     = "pool"    RegressionModel.setup_anndata(        adata=adata_ref,        batch_key=BATCH_KEY,        labels_key=CELL_TYPE_KEY,    )    # ── Train ──────────────────────────────────────────────────────────────    mod = RegressionModel(adata_ref)    mod.view_anndata_setup()    torch.set_num_threads(os.cpu_count())    print(f"Using {os.cpu_count()} CPU threads")    mod.train(        max_epochs=250,        accelerator='cpu',        batch_size=4096,        datasplitter_kwargs={            "num_workers": 0,       # 0 = no multiprocessing (safest on Windows)            "persistent_workers": False,        },    )    # ── Export & save ──────────────────────────────────────────────────────    adata_ref = mod.export_posterior(        adata_ref,        sample_kwargs={'num_samples': 1000, 'batch_size': 2500, 'accelerator': 'cpu'}    )    mod.save(ref_run_name, overwrite=True)    # ── QC plots ───────────────────────────────────────────────────────────    mod.plot_history(20)    plt.savefig(f"{ref_run_name}/train_history.png")    plt.clf()    mod.plot_QC()    plt.savefig(f"{ref_run_name}/train_qc.png")    plt.clf()    # ── Extract signature matrix ───────────────────────────────────────────    inf_aver = adata_ref.varm['means_per_cluster_mu_fg'][        [f'means_per_cluster_mu_fg_{i}' for i in adata_ref.uns['mod']['factor_names']]    ].copy()    inf_aver.columns = adata_ref.uns['mod']['factor_names']    inf_aver.to_csv(f"{ref_run_name}/reference_signatures.csv")    print("Cell types found:", inf_aver.columns.tolist())    print("Signature matrix:", inf_aver.shape)